from lib10 import *
M='maths'
def B(ch,cn,t,tn,*a,**k): build(M,ch,t,tn,*a,cname=cn,tname=tn,**k)
A="Both A and R are true and R explains A"
C,CN='areas-related-to-circles','Areas Related to Circles'
B(C,CN,'arc-length-and-sector-area','Length of an arc and area of a sector',
 "A slice of pizza",
 "A pizza slice is a sector of a circle. How much cheese covers it, and how long is its crust edge? A simple fraction of the whole circle answers both.",
 [("The circumference of a circle is 2 pi r and its area is pi r squared, where r is the radius.","2 pi r and pi r^2"),
  ("A sector is the region between two radii and the arc between them. Its angle at the centre is theta degrees.","sector, angle theta"),
  ("A sector is theta by 360 of the whole circle. So its area is theta/360 times pi r squared.","area = theta/360 x pi r^2"),
  ("The length of its arc is theta/360 times 2 pi r.","arc = theta/360 x 2 pi r"),
  ("Example: radius 6 cm and angle 60 degrees. Area = 60/360 x pi x 36 = 6 pi cm squared.","6 pi cm^2"),
  ("The smaller sector is the minor sector and the larger one is the major sector. The two angles add up to 360 degrees.","minor and major sector"),
  ("For a major sector, use 360 minus theta as its angle, or subtract the minor sector from the whole circle.","360 - theta"),
  ("Use pi = 22/7 unless the question says otherwise, and give the unit as square centimetres for area.","pi = 22/7")],
 ("Find the area of a sector of angle 90 degrees in a circle of radius 14 cm.",[("Area = 90/360 x 22/7 x 14 x 14.","Quarter of the circle."),("= 1/4 x 22/7 x 196 = 1/4 x 616.","Simplify."),("= 154 cm squared.","Final answer with the unit.")]),
 ("How do you find the area and arc length of a sector?",["Fraction theta/360","Area uses pi r^2","Arc uses 2 pi r"],["Using the area formula for arc length"]),
 ["Arc length = (theta/360) x 2 pi r.","Area of sector = (theta/360) x pi r^2.","Major sector uses 360 - theta."],
 [mcq("r1-as1",1,"The area of a sector of angle theta in a circle of radius r is","(theta/360) x pi r^2",[("(theta/360) x 2 pi r","That is the arc length."),("theta x pi r","Not a formula.")],"Fraction of the circle."),
  num("r1-as2",1,"Fraction of a circle for a 90 degree sector, as a decimal",0.25,"90/360.",[(0.5,"That is 180 degrees.")]),
  num("r2-as3",2,"Arc length for 60 degrees, r = 21 cm (pi = 22/7), in cm",22,"1/6 x 2 x 22/7 x 21 = 22.",[(44,"Take 60/360.")]),
  mcq("r2-as4",2,"Assertion (A): A 180 degree sector is half the circle. Reason (R): 180/360 = 1/2.",A,[("A true, R false","R is correct."),("A false, R true","Half circle.")],"Fraction."),
  num("r2-as5",2,"Area of a quadrant of radius 14 cm (pi = 22/7), cm squared",154,"Quarter of 616.",[(616,"Take 1/4.")]),
  num("r3-as6",3,"Angle of a minor sector is 80 degrees, the major sector angle",280,"360 - 80.",[(100,"Subtract from 360.")]),
  tf("r3-as7",3,"The area of a sector depends on the angle at the centre.",True,"It is proportional to the angle."),
  mcq("r3-as8",3,"Case study: A 7 m long rope tied to a post lets a goat graze a quadrant. Area grazed (pi = 22/7)","38.5 m squared",[("154 m squared","That is a full circle."),("77 m squared","That is a semicircle.")],"1/4 x 22/7 x 49.")])
B(C,CN,'segment-of-a-circle','Area of a segment and combinations',
 "The bite out of a circle",
 "A chord cuts a circle into two parts called segments. Finding their area needs a sector and a triangle.",
 [("A segment is the region between a chord and the arc it cuts off.","segment"),
  ("Area of a minor segment = area of the sector minus area of the triangle formed by the two radii and the chord.","segment = sector - triangle"),
  ("For a right angle at the centre with radius r, the sector area is pi r^2/4 and the triangle area is r^2/2.","quadrant case"),
  ("For a 60 degree angle, the triangle is equilateral and its area is root 3/4 times r squared.","60 degrees: equilateral"),
  ("For a major segment, find the area of the circle minus the minor segment.","major segment"),
  ("Many problems combine sectors, squares and triangles: flower beds, logos, clock hands, windscreen wipers.","combined figures"),
  ("For a wiper sweep, area swept = sector of the larger radius minus sector of the smaller radius.","annulus sector"),
  ("Draw and label the figure first, and break it into pieces whose areas you know.","split into parts")],
 ("Find the area of the minor segment of a circle of radius 10 cm for a central angle of 90 degrees (pi = 3.14).",[("Sector = 90/360 x 3.14 x 100 = 78.5 cm^2.","Quarter circle."),("Triangle = 1/2 x 10 x 10 = 50 cm^2.","Right triangle of two radii."),("Segment = 78.5 - 50 = 28.5 cm^2.","Subtract.")]),
 ("How do you find the area of a segment?",["Sector area","Minus triangle area","Draw the figure"],["Adding the triangle instead of subtracting"]),
 ["Minor segment = sector - triangle.","Major segment = circle - minor segment.","Split combined figures into known shapes."],
 [mcq("r1-sg1",1,"Segment area = sector area","minus triangle area",[("plus triangle area","The triangle is inside the sector."),("times triangle area","Areas are subtracted.")],"Remove the triangle."),
  tf("r1-sg2",1,"A chord cuts a circle into two segments.",True,"Minor and major."),
  num("r2-sg3",2,"Area of a right triangle with legs 10 and 10",50,"1/2 x 10 x 10.",[(100,"Use 1/2.")]),
  mcq("r2-sg4",2,"Assertion (A): The area of a quadrant of radius r is pi r^2/4. Reason (R): The central angle is 90 degrees.",A,[("A true, R false","R is correct."),("A false, R true","90/360 = 1/4.")],"Quarter circle."),
  num("r2-sg5",2,"Area of minor segment = 78.5 - 50, in cm squared",28.5,"Subtract.",[(128.5,"It is subtracted.")]),
  mcq("r3-sg6",3,"A 60 degree sector's triangle is","equilateral",[("right-angled","Angle is 60."),("scalene","Two radii are equal.")],"Isosceles with 60 degrees gives equilateral."),
  tf("r3-sg7",3,"The area of the major segment equals the circle area minus the minor segment.",True,"Together they form the circle."),
  num("r3-sg8",3,"Wiper sweeps 120 degrees between radii 7 and 14 cm. Using pi = 22/7, area in cm squared? (1/3)(22/7)(196 - 49) =",154,"1/3 x 22/7 x 147 = 154.",[(462,"Use 1/3.")])])
# Ch12
C,CN='surface-areas-and-volumes','Surface Areas and Volumes'
B(C,CN,'surface-area-of-combined-solids','Surface area of combination of solids',
 "A toy made of parts",
 "A toy rocket is a cone on a cylinder, a medicine capsule is a cylinder with two hemispheres. Joining solids changes which surfaces are visible.",
 [("The basic solids are cuboid, cube, cylinder, cone, sphere and hemisphere.","basic solids"),
  ("Curved surface area of a cylinder is 2 pi r h, of a cone is pi r l with l = root(r^2 + h^2), of a sphere is 4 pi r^2 and of a hemisphere is 2 pi r^2.","CSA formulas"),
  ("When two solids are joined, the area where they join is hidden, so it is not part of the total surface area.","hidden surface"),
  ("For a cone on a cylinder: TSA = CSA of cone + CSA of cylinder + area of the base circle of the cylinder.","cone on cylinder"),
  ("For a capsule: TSA = CSA of cylinder + CSA of two hemispheres.","capsule"),
  ("For a hemisphere on a cube, subtract the circle covered on the cube, then add the curved area of the hemisphere.","hemisphere on cube"),
  ("Draw the combined solid and list which surfaces are visible before you calculate.","list visible faces"),
  ("Use the same units everywhere and write square units.","square units")],
 ("A toy is a cone on a hemisphere, both of radius 3.5 cm. Total height 15.5 cm. Find its surface area (pi = 22/7).",[("Cone height = 15.5 - 3.5 = 12 cm, slant height l = root(144 + 12.25) = 12.5 cm.","Find the slant height."),("CSA cone = 22/7 x 3.5 x 12.5 = 137.5 cm^2, hemisphere = 2 x 22/7 x 12.25 = 77 cm^2.","Add visible curved surfaces."),("Total = 214.5 cm^2.","Joint circle is hidden.")]),
 ("How do you find the surface area of joined solids?",["Add the visible surfaces","Ignore the joined face","Use correct formulas"],["Adding the hidden base"]),
 ["Hidden joined faces are not counted.","TSA of combined solid = sum of visible areas.","Cone slant height l = √(r^2 + h^2)."],
 [mcq("r1-sa1",1,"The curved surface area of a hemisphere is","2 pi r^2",[("4 pi r^2","That is a full sphere."),("3 pi r^2","That is the total surface area of a hemisphere.")],"Half of 4 pi r^2."),
  tf("r1-sa2",1,"When two solids are joined, the joint surface is not part of the total surface area.",True,"It is hidden inside."),
  num("r2-sa3",2,"Slant height of a cone with r = 3 and h = 4",5,"root(9 + 16).",[(7,"Use Pythagoras.")]),
  mcq("r2-sa4",2,"Assertion (A): The TSA of a capsule is CSA of the cylinder plus two hemispheres. Reason (R): The cylinder's circular ends are covered by the hemispheres.",A,[("A true, R false","R is correct."),("A false, R true","The ends are hidden.")],"No flat faces remain."),
  num("r2-sa5",2,"CSA of a cylinder r = 7, h = 10 (pi = 22/7)",440,"2 x 22/7 x 7 x 10.",[(220,"Include the factor 2.")]),
  mcq("r3-sa6",3,"Surface area of a sphere of radius r","4 pi r^2",[("2 pi r^2","That is a hemisphere."),("pi r^2","That is a circle.")],"Standard."),
  tf("r3-sa7",3,"Slant height of a cone is always longer than its height.",True,"It is the hypotenuse."),
  num("r3-sa8",3,"Radius 7, TSA of a hemisphere uses 3 pi r^2 (pi = 22/7)",462,"3 x 22/7 x 49.",[(308,"Add the base circle.")])])
B(C,CN,'volume-of-combined-solids','Volume of combination of solids',
 "How much does it hold?",
 "A tank, a test tube or an ice-cream cone with ice cream on top: volumes of combined solids tell us how much they hold.",
 [("Volume formulas: cuboid l b h, cylinder pi r squared h, cone one-third pi r squared h, sphere four-thirds pi r cubed, hemisphere two-thirds pi r cubed.","volume formulas"),
  ("For combined solids, add the volumes of the parts. Joining does not hide any volume.","add volumes"),
  ("A cone on a cylinder: V = pi r squared h(cylinder) + one-third pi r squared h(cone).","cone + cylinder"),
  ("A capsule: V = pi r squared h + two-thirds pi r cubed x 2 for both hemispheres.","capsule volume"),
  ("If a solid is melted and recast, the volume stays the same: V(old) = V(new) x number of pieces.","melting and recasting"),
  ("When a solid is dropped into water, the water rises by the volume of the solid.","displacement"),
  ("Convert units carefully: 1 litre = 1000 cubic centimetres.","1 litre = 1000 cm^3"),
  ("Draw the solid, mark the radii and heights, and then compute each part.","draw and mark")],
 ("A metallic sphere of radius 4.2 cm is melted and recast into a cylinder of radius 6 cm. Find the height (pi cancels).",[("Sphere volume = 4/3 pi (4.2)^3.","Volume of sphere."),("Cylinder volume = pi (36) h. Equate: 36h = 4/3 x 74.088 = 98.784.","Volume is conserved."),("h = 2.744 cm.","Solve.")]),
 ("How do you handle volume of combined solids?",["Add the volumes","Melting keeps volume constant","Use the right formulas"],["Subtracting volumes for joined solids"]),
 ["Volume of a combined solid is the sum of its parts.","Melting and recasting preserves volume.","1 litre = 1000 cm^3."],
 [mcq("r1-vc1",1,"Volume of a cone","(1/3) pi r^2 h",[("pi r^2 h","That is a cylinder."),("(4/3) pi r^3","That is a sphere.")],"One-third of the cylinder."),
  num("r1-vc2",1,"Volume of a cuboid 2 x 3 x 4",24,"2 x 3 x 4.",[(9,"Multiply all.")]),
  num("r2-vc3",2,"Cylinder r = 7, h = 10 (pi = 22/7), volume",1540,"22/7 x 49 x 10.",[(440,"That is the curved area.")]),
  mcq("r2-vc4",2,"Assertion (A): Volume stays the same when a solid is melted and recast. Reason (R): Melting does not change the amount of matter.",A,[("A true, R false","R is correct."),("A false, R true","Matter is conserved.")],"Volume conserved."),
  num("r2-vc5",2,"Volume of a sphere radius 3 in terms of pi: coefficient of pi",36,"4/3 x 27.",[(12,"Check cube.")]),
  mcq("r3-vc6",3,"A cone has the same base and height as a cylinder. Its volume is","one-third of the cylinder",[("half of the cylinder","One-third."),("equal","Smaller.")],"Standard result."),
  tf("r3-vc7",3,"1 litre equals 1000 cubic centimetres.",True,"Standard conversion."),
  num("r3-vc8",3,"A cube of side 10 cm is filled with 1 cm cubes. How many cubes fit?",1000,"Volume 1000 cm^3 divided by 1 cm^3 each.",[(100,"Volume uses the cube of the side, 10 x 10 x 10.")])])
# Ch13
C,CN='statistics','Statistics'
B(C,CN,'mean-of-grouped-data','Mean of grouped data',
 "Marks of a whole class",
 "A teacher has marks of 100 students grouped in class intervals. Listing them all is tedious; the mean of grouped data gives a quick average.",
 [("In grouped data, observations are put into class intervals with frequencies.","class intervals"),
  ("The class mark is the mid-point: (upper limit + lower limit) divided by 2.","class mark"),
  ("Direct method: mean = sum of f x divided by sum of f, where x is the class mark.","mean = Σfx / Σf"),
  ("Assumed mean method: pick a convenient a and let d = x - a. Then mean = a + Σfd / Σf.","a + Σfd/Σf"),
  ("Step deviation method: with class width h, let u = (x - a)/h. Then mean = a + (Σfu/Σf) x h.","a + (Σfu/Σf) h"),
  ("These assume that the frequency of each class is centred at its class mark.","class mark assumption"),
  ("Make a table with columns for class, frequency, class mark and the product, then total the columns.","make a table"),
  ("Use the method that gives the smallest numbers to avoid arithmetic mistakes.","choose a method")],
 ("Find the mean for classes 0-10, 10-20, 20-30 with frequencies 5, 8, 7.",[("Class marks: 5, 15, 25. Products f x: 25, 120, 175.","Build the table."),("Σf = 20, Σfx = 320.","Totals."),("Mean = 320/20 = 16.","Divide.")]),
 ("How do you find the mean of grouped data?",["Class marks","Σfx / Σf","Shortcut methods"],["Using class limits instead of class marks"]),
 ["Class mark = (lower + upper)/2.","Direct, assumed mean and step deviation methods all give the same mean.","Frequency is assumed to be centred at the class mark."],
 [num("r1-mg1",1,"Class mark of 10-20",15,"(10 + 20)/2.",[(10,"Class mark is the mid-point of the limits.")]),
  tf("r1-mg2",1,"Mean = Σfx/Σf for grouped data.",True,"Direct method."),
  num("r2-mg3",2,"If Σfx = 600 and Σf = 40, mean =",15,"600/40.",[(24,"Divide.")]),
  mcq("r2-mg4",2,"Assertion (A): The mean of grouped data is only an estimate. Reason (R): We assume each class's frequency is at the class mark.",A,[("A true, R false","R explains why."),("A false, R true","It is an estimate.")],"Class mark assumption."),
  num("r2-mg5",2,"Class mark of 25-35",30,"(25 + 35)/2.",[(25,"Class mark is the mid-point of the limits.")]),
  mcq("r3-mg6",3,"In step deviation, u = (x - a)/h where h is","class width",[("frequency","Frequency is how many observations lie in a class, not its width."),("class mark","The class mark is the mid-point of the class.")],"Width of the class."),
  tf("r3-mg7",3,"The three methods give different means.",False,"They are the same mean computed differently."),
  num("r3-mg8",3,"Frequencies 2, 3, 5 and class marks 10, 20, 30; Σfx",230,"20 + 60 + 150.",[(60,"Add all products.")])])
B(C,CN,'mode-and-median-of-grouped-data','Mode, median and cumulative frequency',
 "Most common and middle value",
 "Which marks occurred most often in a test? Which mark splits the class into two equal halves? Mode and median answer these for grouped data.",
 [("The modal class is the class with the highest frequency.","modal class"),
  ("Mode = l + ((f1 - f0)/(2 f1 - f0 - f2)) x h, where l is the lower limit of the modal class, f1 its frequency, f0 and f2 the frequencies before and after, and h the width.","mode formula"),
  ("The cumulative frequency of a class is the sum of the frequencies of that class and all classes before it.","cumulative frequency"),
  ("The median class is the class whose cumulative frequency is just greater than n/2.","median class"),
  ("Median = l + ((n/2 - cf)/f) x h, where cf is the cumulative frequency of the class before the median class.","median formula"),
  ("Classes must be continuous before using these formulas. Make them continuous if there are gaps.","continuous classes"),
  ("Relationship: 3 median = mode + 2 mean, an empirical relation.","3 median = mode + 2 mean"),
  ("An ogive is a graph of cumulative frequency, and the point where n/2 meets the curve gives the median.","ogive")],
 ("Find the mode for 0-10, 10-20, 20-30, 30-40 with frequencies 3, 8, 15, 6.",[("Modal class is 20-30; f1 = 15, f0 = 8, f2 = 6, l = 20, h = 10.","Highest frequency."),("Mode = 20 + (7/(30 - 14)) x 10 = 20 + 70/16.","Substitute."),("Mode = 24.375.","Compute.")]),
 ("How do you find the median of grouped data?",["Cumulative frequency","Median class (n/2)","Apply the formula"],["Forgetting to use n/2"]),
 ["Mode = l + [(f1 - f0)/(2f1 - f0 - f2)] h.","Median = l + [(n/2 - cf)/f] h.","3 Median = Mode + 2 Mean."],
 [mcq("r1-mm1",1,"The modal class has the","highest frequency",[("lowest frequency","It is the most frequent class."),("highest class mark","Not related.")],"Definition."),
  tf("r1-mm2",1,"Cumulative frequency is a running total of frequencies.",True,"Definition."),
  num("r2-mm3",2,"n = 40, find n/2",20,"40/2.",[(40,"Halve it.")]),
  mcq("r2-mm4",2,"Assertion (A): Median class is where cumulative frequency first exceeds n/2. Reason (R): The median is the middle observation.",A,[("A true, R false","R explains it."),("A false, R true","Both are true.")],"Median position."),
  num("r2-mm5",2,"Mode of classes where f1 = 15, f0 = 8, f2 = 6, l = 20, h = 10 (answer to 3 places)",24.375,"20 + 70/16.",[(25,"Substitute into the formula carefully.")]),
  mcq("r3-mm6",3,"If mean = 20 and mode = 14, median using 3 median = mode + 2 mean is","18",[("17","Compute: (14 + 40)/3."),("34","Divide by 3.")],"54/3."),
  tf("r3-mm7",3,"An ogive plots cumulative frequency.",True,"Definition."),
  num("r3-mm8",3,"Cumulative frequencies up to the class before the median class is cf = 12 and f = 8. If n/2 = 20 find (n/2 - cf)/f",1,"(20 - 12)/8.",[(8,"Divide by f.")])])
# Ch14
C,CN='probability','Probability'
B(C,CN,'theoretical-probability','Theoretical probability',
 "Heads or tails?",
 "Before a cricket match the captains toss a coin. Each side has the same chance. Probability measures how likely an event is on a scale of 0 to 1.",
 [("An experiment such as tossing a coin or rolling a die has outcomes. An event is a collection of outcomes.","experiment and event"),
  ("Probability of an event E = number of outcomes favourable to E divided by the number of all possible outcomes, when outcomes are equally likely.","P(E) = favourable / total"),
  ("For a fair die, P(getting 4) = 1/6 and P(even number) = 3/6 = 1/2.","die example"),
  ("An event that is sure to happen has probability 1. An impossible event has probability 0.","sure = 1, impossible = 0"),
  ("So the probability of any event lies between 0 and 1.","0 <= P(E) <= 1"),
  ("The probabilities of all elementary events of an experiment add up to 1.","sum = 1"),
  ("P(E) + P(not E) = 1. The event not E is the complement of E.","complementary events"),
  ("For a deck of 52 cards, P(red card) = 26/52 = 1/2. P(ace of spades) = 1/52.","cards")],
 ("A bag has 3 red, 5 white and 2 blue balls. One is drawn at random. Find P(white) and P(not red).",[("Total = 10 balls.","Count all outcomes."),("P(white) = 5/10 = 1/2.","Favourable = 5."),("P(not red) = 1 - 3/10 = 7/10.","Complement rule.")]),
 ("What is probability and what are its limits?",["Favourable by total","Between 0 and 1","P(E) + P(not E) = 1"],["Writing probabilities greater than 1"]),
 ["P(E) = favourable outcomes / all possible outcomes.","Sure event 1, impossible event 0, so 0 <= P(E) <= 1.","P(E) + P(not E) = 1."],
 [mcq("r1-tp1",1,"The probability of a sure event is","1",[("0","That is an impossible event."),("0.5","That is a fair coin.")],"Always happens."),
  tf("r1-tp2",1,"Probability can be greater than 1.",False,"It lies between 0 and 1."),
  num("r2-tp3",2,"A die is rolled. P(a number greater than 4) as a decimal rounded to 2 places",0.33,"2/6.",[(0.5,"Count 5 and 6.")]),
  mcq("r2-tp4",2,"Assertion (A): If P(E) = 0.3 then P(not E) = 0.7. Reason (R): P(E) + P(not E) = 1.",A,[("A true, R false","R is correct."),("A false, R true","1 - 0.3.")],"Complement."),
  num("r2-tp5",2,"Bag has 3 red and 5 white balls. Total outcomes",8,"3 + 5.",[(5,"Count all.")]),
  mcq("r3-tp6",3,"Probability of getting a head in one toss","1/2",[("1","Not sure."),("0","Not impossible.")],"Two equally likely outcomes."),
  tf("r3-tp7",3,"The sum of the probabilities of all elementary events is 1.",True,"Total certainty."),
  num("r3-tp8",3,"P(drawing a king from 52 cards) as the number of kings",4,"4/52.",[(1,"There are four kings, one in each suit.")])])
B(C,CN,'probability-problems-with-dice-and-cards','Probability with coins, dice and cards',
 "Many chances",
 "Two coins, two dice, a pack of cards. Listing outcomes in a table makes probability problems easy.",
 [("When two coins are tossed, the outcomes are HH, HT, TH and TT, four equally likely outcomes.","two coins"),
  ("P(two heads) = 1/4 and P(at least one head) = 3/4.","at least one head"),
  ("When two dice are thrown, there are 36 equally likely outcomes.","36 outcomes"),
  ("P(sum 7) = 6/36 = 1/6 because the pairs (1,6), (2,5), (3,4), (4,3), (5,2), (6,1) work.","sum of 7"),
  ("P(doublet) = 6/36 = 1/6, and P(sum 12) = 1/36.","doublet"),
  ("A deck has 52 cards in four suits, 13 per suit, with 12 face cards and 4 aces.","52 cards"),
  ("The theoretical probability predicts. The experimental probability comes from actual trials. With many trials they come close.","experimental vs theoretical"),
  ("List the sample space in an orderly table so that you do not miss an outcome.","sample space")],
 ("Two dice are thrown. Find P(sum is 8).",[("Total outcomes = 36.","All pairs."),("Pairs giving 8: (2,6), (3,5), (4,4), (5,3), (6,2) = 5.","List them."),("P = 5/36.","Divide.")]),
 ("How do you solve probability for dice and cards?",["List outcomes","Count favourable","Use the complement if easier"],["Missing pairs like (4,4)"]),
 ["Two coins: 4 outcomes; two dice: 36 outcomes.","Make an orderly list of favourable outcomes.","Experimental probability approaches theoretical with more trials."],
 [num("r1-pd1",1,"Number of outcomes for two dice",36,"6 x 6.",[(12,"Multiply.")]),
  mcq("r1-pd2",1,"P(two tails in 2 tosses)","1/4",[("1/2","One in four outcomes."),("3/4","That is at least one tail.")],"TT only."),
  num("r2-pd3",2,"Two dice. Number of pairs with sum 7",6,"(1,6) to (6,1).",[(5,"Count all.")]),
  mcq("r2-pd4",2,"Assertion (A): P(sum 7) = 1/6 for two dice. Reason (R): 6 of the 36 outcomes have sum 7.",A,[("A true, R false","R is correct."),("A false, R true","6/36 = 1/6.")],"Count the favourable outcomes carefully."),
  num("r2-pd5",2,"Number of aces in a deck",4,"One per suit.",[(1,"There is one in each suit.")]),
  mcq("r3-pd6",3,"P(a doublet) when two dice are thrown","1/6",[("1/36","That is a particular double."),("1/2","Too high.")],"6 of 36."),
  tf("r3-pd7",3,"Theoretical probability predicts what should happen.",True,"Based on assumptions."),
  num("r3-pd8",3,"A card is drawn from 52. Number of face cards",12,"Jack, queen, king in 4 suits.",[(16,"Aces and tens are not face cards.")])])
